import{_ as i,a0 as n,w as p,s as d,ao as o,I as l,x as e,a1 as a,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"Web 開發人員喜歡 Brackets 文本編輯器的原因 | LCTT x X-CMD","titleTemplate":false,"description":"Web 開發人員喜歡 Brackets 文本編輯器的原因 | LCTT (202012) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Web 開發人員喜歡 Brackets 文本編輯器的原因 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Web 開發人員喜歡 Brackets 文本編輯器的原因 | LCTT (202012) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202012/20201213 What web developers love about the Brackets text editor","title":"Web 開發人員喜歡 Brackets 文本編輯器的原因","tag":"202012","desc":""},"relativePath":"202012/20201213 What web developers love about the Brackets text editor.md","filePath":"[post].md"}'),u={name:"202012/20201213 What web developers love about the Brackets text editor.md"};function k(b,t,f,m,B,T){const r=n("Link");return p(),d("div",null,[t[26]||(t[26]=o('<h1 id="web-開發人員喜歡-brackets-文本編輯器的原因" tabindex="-1">Web 開發人員喜歡 Brackets 文本編輯器的原因 <a class="header-anchor" href="#web-開發人員喜歡-brackets-文本編輯器的原因" aria-label="Permalink to “Web 開發人員喜歡 Brackets 文本編輯器的原因”">​</a></h1><blockquote><p>這個基礎的編輯器是面向 Web 開發人員的，它支持多種編程語言，並提供了大量的擴展，使其成為你自己的編輯器。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202012/25/092259zy4xvxs4axmysuf9.jpg" alt=""></p><p>Brackets 文本編輯器是主要面向 Web 開發人員的編輯器。恰如其分的是，它的“編輯”菜單中充滿了對 Web 編程語言用户特別有用的功能，主要是 HTML、CSS 和 Javascript 的經典組合。</p><p>但是，它還支持許多與互聯網相關的語言和格式，包括 XML、Markdown、YAML 和 JSON、PHP、Lua、Java 和 Python，以及一些常見的通用語言，例如 C、C++，甚至是 <code>diff</code> 命令的輸出。</p><h3 id="安裝-brackets" tabindex="-1">安裝 Brackets <a class="header-anchor" href="#安裝-brackets" aria-label="Permalink to “安裝 Brackets”">​</a></h3>',6)),l("p",null,[t[1]||(t[1]=e("Brackets 可以從 ",-1)),a(r,{href:"http://brackets.io/"},{default:s(()=>[...t[0]||(t[0]=[e("Brackets 網站",-1)])]),_:1}),t[2]||(t[2]=e("安裝到 Linux、Windows 和 macOS 上。",-1))]),l("p",null,[t[4]||(t[4]=e("另外，在 Linux 上，你可以從 ",-1)),a(r,{href:"https://flathub.org/apps/details/io.brackets.Brackets"},{default:s(()=>[...t[3]||(t[3]=[e("flathub.org",-1)])]),_:1}),t[5]||(t[5]=e(" 以 Flatpak 安裝。",-1))]),t[27]||(t[27]=l("p",null,[l("img",{src:"https://opensource.com/sites/default/files/screenshot_2020-12-02_at_16.26.58.png",alt:"Brackets editor",title:"Brackets editor"})],-1)),t[28]||(t[28]=l("h3",{id:"使用-brackets",tabindex:"-1"},[e("使用 Brackets "),l("a",{class:"header-anchor",href:"#使用-brackets","aria-label":"Permalink to “使用 Brackets”"},"​")],-1)),l("p",null,[t[8]||(t[8]=e("在大多數時候，Brackets 是一個“普通”的文本編輯器，其功能類似於 ",-1)),a(r,{href:"https://linux.cn/article-12942-1.html"},{default:s(()=>[...t[6]||(t[6]=[e("jEdit",-1)])]),_:1}),t[9]||(t[9]=e(" 或 ",-1)),a(r,{href:"https://linux.cn/article-12938-1.html"},{default:s(()=>[...t[7]||(t[7]=[e("Medit",-1)])]),_:1}),t[10]||(t[10]=e("。有語法高亮、可配置的製表符間距、字符編碼設置等等。這些都可以在窗口底部的狀態欄中找到。",-1))]),t[29]||(t[29]=o('<p>在“視圖”菜單中，有主題設置、行號、自動換行，甚至還有分割窗口的選項，這樣你可以在一個窗口中看到兩個文件。</p><p>然而，在“編輯”菜單中，有一些的特別用於編程的功能。以下是我最喜歡的一些功能：</p><ul><li>使用 <code>Ctrl+[</code> 或 <code>Ctrl+]</code> 鍵盤快捷鍵來縮進和取消縮進文本塊，這不僅對保持 HTML、CSS 和 Javascript 的整潔很有用，而且對 Python 代碼也很重要。</li><li>用 <code>Ctrl+/</code> 把一行變成註釋。Brackets 標記註釋的方式取決於你所使用的語言，所以無論你的文檔是否使用斜線、破折號、箭頭、井號或其他任何類型註釋，這個功能都可以使用。</li><li>用 <code>Shift+Ctrl+Up</code> 或 <code>Shift+Ctrl+Down</code> 在文檔中將一行向上或向下移動。</li><li>用 <code>Shift+Ctrl+D</code> 刪除整個一行。</li><li>用 <code>Ctrl+D</code> 複製整個一行。</li></ul><p>這些都是看似小眾的功能，你可能認為不會經常使用，但一旦你擁有了它們，你就會對它們產生依賴。</p><h3 id="擴展" tabindex="-1">擴展 <a class="header-anchor" href="#擴展" aria-label="Permalink to “擴展”">​</a></h3><p>Brackets 還可以接受擴展，因此你和其他編碼者可以添加擴展到功能中。要查看有哪些可用的擴展，請單擊“文件”菜單並選擇“擴展管理器”。有各種各樣的擴展，包括用於調整代碼格式的 Beautify、用於其他語言的多個支持包、用於轉到標籤開頭或結尾的功能等等。</p><p>無論編輯器是否適合你，擴展可以使一個編輯器變得不同，所以如果你嘗試 Brackets 並享受它的一切，但缺少一些重要的功能，在你放棄它之前，請瀏覽一下可用的擴展。</p><h3 id="嘗試-brackets" tabindex="-1">嘗試 Brackets <a class="header-anchor" href="#嘗試-brackets" aria-label="Permalink to “嘗試 Brackets”">​</a></h3><p>Brackets 是一個有點低調的編輯器。雖然它宣傳自己是 “Web 代碼編輯器”，但實際上它是一個不錯的通用編輯器，併為常見的 Web 工具鏈加入了一些額外的功能。如果你喜歡 Brackets 的外觀和它所提供的功能，不妨一試！</p><hr>',10)),l("p",null,[t[12]||(t[12]=e("via: ",-1)),a(r,{href:"https://opensource.com/article/20/12/brackets"},{default:s(()=>[...t[11]||(t[11]=[e("https://opensource.com/article/20/12/brackets",-1)])]),_:1})]),l("p",null,[t[17]||(t[17]=e("作者：",-1)),a(r,{href:"https://opensource.com/users/seth"},{default:s(()=>[...t[13]||(t[13]=[e("Seth Kenlon",-1)])]),_:1}),t[18]||(t[18]=e(" 選題：",-1)),a(r,{href:"https://github.com/lujun9972"},{default:s(()=>[...t[14]||(t[14]=[e("lujun9972",-1)])]),_:1}),t[19]||(t[19]=e(" 譯者：",-1)),a(r,{href:"https://github.com/geekpi"},{default:s(()=>[...t[15]||(t[15]=[e("geekpi",-1)])]),_:1}),t[20]||(t[20]=e(" 校對：",-1)),a(r,{href:"https://github.com/wxy"},{default:s(()=>[...t[16]||(t[16]=[e("wxy",-1)])]),_:1})]),l("p",null,[t[23]||(t[23]=e("本文由 ",-1)),a(r,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[21]||(t[21]=[e("LCTT",-1)])]),_:1}),t[24]||(t[24]=e(" 原創編譯，",-1)),a(r,{href:"https://linux.cn/"},{default:s(()=>[...t[22]||(t[22]=[e("Linux中國",-1)])]),_:1}),t[25]||(t[25]=e(" 榮譽推出",-1))])])}const g=i(u,[["render",k]]);export{h as __pageData,g as default};
